import{_ as o,o as s,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant API v1 — Resellers","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Resellers | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-resellers"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Resellers | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-resellers"}]]},"headers":[],"relativePath":"api/tenant-v1-resellers.md","filePath":"api/tenant-v1-resellers.md","lastUpdated":1786147061000}'),t={name:"api/tenant-v1-resellers.md"};function d(l,e,i,c,n,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-resellers" tabindex="-1">Tenant API v1 — Resellers <a class="header-anchor" href="#tenant-api-v1-—-resellers" aria-label="Permalink to &quot;Tenant API v1 — Resellers&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:resellers</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>resellers.assign</code> (and not superadmin), list/stats/view include resellers where <code>assigned_to</code> is the current user <strong>or</strong> <code>user_id</code> is the current user. Update without assign is limited to assignee.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-resellers-stats" tabindex="-1">GET <code>/resellers/stats</code> <a class="header-anchor" href="#get-resellers-stats" aria-label="Permalink to &quot;GET `/resellers/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total_resellers</code>, <code>my_resellers</code>, <code>unassigned</code>, <code>active</code>, <code>inactive</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="resellers-crud" tabindex="-1">Resellers CRUD <a class="header-anchor" href="#resellers-crud" aria-label="Permalink to &quot;Resellers CRUD&quot;">​</a></h2><h3 id="get-resellers" tabindex="-1">GET <code>/resellers</code> <a class="header-anchor" href="#get-resellers" aria-label="Permalink to &quot;GET `/resellers`&quot;">​</a></h3><p>Query: <code>search</code> (name, email, phone, company_name), <code>status</code> (<code>active</code>|<code>inactive</code>), <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_resellers</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><h3 id="post-resellers" tabindex="-1">POST <code>/resellers</code> <a class="header-anchor" href="#post-resellers" aria-label="Permalink to &quot;POST `/resellers`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>company_name</code>, <code>notes</code>, <code>status</code> (<code>active</code>|<code>inactive</code>, default <code>active</code>), <code>commission_rate</code> (0–100), <code>owner_commission_rate</code> (0–100), <code>assigned_to</code>.</p><p>Permission: <code>resellers.create</code>.</p><h3 id="get-resellers-id" tabindex="-1">GET <code>/resellers/{id}</code> <a class="header-anchor" href="#get-resellers-id" aria-label="Permalink to &quot;GET `/resellers/{id}`&quot;">​</a></h3><p>Includes assignee, creator, linked login <code>user</code> when present, plus nested <code>note_entries</code> (threaded notes) and <code>activities</code> (domain timeline). Scalar <code>notes</code> remains the profile field. Soft-deleted → 404 for show.</p><h3 id="put-resellers-id" tabindex="-1">PUT <code>/resellers/{id}</code> <a class="header-anchor" href="#put-resellers-id" aria-label="Permalink to &quot;PUT `/resellers/{id}`&quot;">​</a></h3><p>Partial update of reseller fields (including rates and <code>assigned_to</code> when permitted).</p><p>Permission: <code>resellers.update</code>.</p><h3 id="delete-resellers-id" tabindex="-1">DELETE <code>/resellers/{id}</code> <a class="header-anchor" href="#delete-resellers-id" aria-label="Permalink to &quot;DELETE `/resellers/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>resellers.delete</code>.</p><h3 id="post-resellers-id-restore" tabindex="-1">POST <code>/resellers/{id}/restore</code> <a class="header-anchor" href="#post-resellers-id-restore" aria-label="Permalink to &quot;POST `/resellers/{id}/restore`&quot;">​</a></h3><p>Restore. Permission: <code>resellers.restore</code>.</p><h3 id="delete-resellers-id-force" tabindex="-1">DELETE <code>/resellers/{id}/force</code> <a class="header-anchor" href="#delete-resellers-id-force" aria-label="Permalink to &quot;DELETE `/resellers/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted reseller. Permission: <code>resellers.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-resellers-id-assign" tabindex="-1">POST <code>/resellers/{id}/assign</code> <a class="header-anchor" href="#post-resellers-id-assign" aria-label="Permalink to &quot;POST `/resellers/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>resellers.assign</code>.</p><h3 id="post-resellers-id-invite-login" tabindex="-1">POST <code>/resellers/{id}/invite-login</code> <a class="header-anchor" href="#post-resellers-id-invite-login" aria-label="Permalink to &quot;POST `/resellers/{id}/invite-login`&quot;">​</a></h3><p>Creates a same-workspace user with <strong>only</strong> the <code>reseller</code> role and sets <code>user_id</code>.</p><p>Body: <code>password</code> (required, min 8), optional <code>email</code> (defaults to reseller email), optional <code>name</code> (defaults to reseller name).</p><p>Fails if <code>user_id</code> already set, email missing after defaulting, or email already used in the tenant.</p><p>Permission: <code>resellers.invite</code>. Response <code>201</code>.</p><h3 id="get-resellers-id-timeline" tabindex="-1">GET <code>/resellers/{id}/timeline</code> <a class="header-anchor" href="#get-resellers-id-timeline" aria-label="Permalink to &quot;GET `/resellers/{id}/timeline`&quot;">​</a></h3><p>Paginated domain activity events (<code>ResellerActivity</code>), newest first. Permission: <code>resellers.view</code>.</p><h3 id="post-resellers-id-notes" tabindex="-1">POST <code>/resellers/{id}/notes</code> <a class="header-anchor" href="#post-resellers-id-notes" aria-label="Permalink to &quot;POST `/resellers/{id}/notes`&quot;">​</a></h3><p>Adds a threaded note (<code>{ &quot;body&quot;: string }</code>). Requires <code>resellers.update</code> (and update policy scope). Response <code>201</code> with the note resource; also appends a timeline <code>note_added</code> activity and platform audit <code>reseller_note_added</code>.</p><p>Serialized on show as <code>note_entries</code> (not <code>notes</code>) so the profile scalar is unambiguous.</p><h2 id="invoice-link" tabindex="-1">Invoice link <a class="header-anchor" href="#invoice-link" aria-label="Permalink to &quot;Invoice link&quot;">​</a></h2><p>Customer invoice create/update accepts optional <code>reseller_id</code> (tenant-scoped exists + <code>LinkableReseller</code>). See <a href="/api/tenant-v1-invoices">tenant-v1-invoices.md</a>. Resources expose <code>reseller_id</code> and nested <code>reseller</code> when loaded.</p>',41)])])}const u=o(t,[["render",d]]);export{m as __pageData,u as default};
